import os
import re
import shutil
from typing import List
from zipfile import ZipFile
from taf.rfrl.scrambling_logs_collector.resources.python.logs_purposes import LogPurpose, CNI_86663


PURPOSE_OPTIONS = {
    "REGRESSION": LogPurpose,
    "CNI-86663": CNI_86663
}


class LogsPreparer:
    """Prepare logs for delivery into Log scrambling test environment"""

    def __init__(self, logs: List[str], logs_type: str, log_purpose: str):
        self.logs = logs
        self.logs_type = logs_type
        self.logs_new_paths: List[str] = []
        self.logs_dirpath = ""
        self.log_purpose = log_purpose

    def copy_logs_into_processing_dir_with_new_names(self, processing_dir: str):
        """
        Copies logs into the specified processing directory and renames them according to predefined patterns.
        In case of syslog and scf, new names of copied logs must be compliant with CAPS-V expected file regexes.

        :param processing_dir: Directory where logs will be copied and renamed.

        Important Note:
            If multiple logs share the same parent directory name, they will be renamed to the same filename
            and copied to the same destination path. In such cases, each subsequent log will overwrite the
            previous one, resulting in only the LAST log being preserved. This is the expected behavior.

            Example with multiple logs from same parent directory:
                logs = ["/path/test_results/log1.zip", "/path/test_results/log2.zip"]
                logs_type = "__snapshot__"

                Both logs will be renamed to "test_results.zip" and copied to the same location.
                Only log2.zip content will remain as "test_results.zip" (log1.zip gets overwritten).

        Example:
            logs = ["/home/ute/MN/UTE/robotws/test_results/snapshot.zip"]
            logs_type = "__snapshot__"
            log_purpose = "REGRESSION"
            processing_dir = "/home/user/scrambling_processing_dir"

            logs_preparer = LogsPreparer(logs, logs_type, log_purpose)
            logs_preparer.copy_logs_into_processing_dir_with_new_names(processing_dir)

            # Result:
            # The log will be copied to:
            # /home/user/scrambling_processing_dir/__snapshot__/test_results.zip
        """
        log_name_patterns = {
            '__syslog__': "master_syslog_{}.log",
            '__scf__': "{}_scf.xml",
            '__snapshot__': "{}.zip",
            '__ru_snapshot__': '{}.zip',
            '__screl_classical__': "{}.zip",
            '__screl_vDU__': "{}.zip",
            '__screl_vCU__': "{}.zip",
            '__snapshot_vDU__': "{}.zip",
            '__snapshot_vCU__': "{}.zip",
            '__nop__': "{}.zip"
        }

        # Validation with descriptive error messages for Robot Framework
        if not self.logs:
            raise ValueError("LogsPreparer: No logs provided for processing")

        if self.logs_type not in log_name_patterns:
            supported_types = list(log_name_patterns.keys())
            raise ValueError(f"LogsPreparer: Unsupported logs_type '{self.logs_type}'. "
                             f"Supported types: {supported_types}")

        for log in self.logs:
            if not os.path.exists(log):
                raise FileNotFoundError(f"LogsPreparer: Log file does not exist: {log}")

        # Create the processing directory for the logs
        logs_dirpath = os.path.join(processing_dir, self.logs_type)
        if not os.path.exists(logs_dirpath):
            os.makedirs(logs_dirpath)
        self.logs_dirpath = logs_dirpath

        # Copy logs and rename them
        for log in self.logs:
            logs_dirname = os.path.basename(os.path.dirname(log))  # Extract the parent directory name
            log_new_name = log_name_patterns[self.logs_type].format(logs_dirname)  # Generate new log name
            log_new_path = os.path.join(logs_dirpath, log_new_name)  # Full path for the new log
            shutil.copy(log, log_new_path)  # Copy the log to the new path
            if log_new_path not in self.logs_new_paths:
                self.logs_new_paths.append(log_new_path)  # Append only unique paths

        # Apply extra preparation based on the log purpose
        log_purpose_class = PURPOSE_OPTIONS.get(self.log_purpose, LogPurpose)
        log_purpose_instance = log_purpose_class(self.logs_new_paths)
        self.logs_new_paths = log_purpose_instance.extra_preparation()

    def pack_logs_into_archive(self, pkg_prefix: str) -> str:
        """
        Pack logs of selected type into .zip archive. If logs are already in .zip archive (i.e. snapshot),
        then move it only with new name pkg name consistent with proxy script expectations.

        :param pkg_prefix: Output pkg prefix name, i.e.
                           SBTS23R2_ENB_0000_000588_000000_+23-04-2023-23:30:44+CRT_ASIL_ABIO_pack_2
        :return: File path to the .zip logs package

        Example:
            logs_dirpath = "/home/user/scrambling_processing_dir/__snapshot__"
            logs_type = "__snapshot__"
            pkg_prefix = "SBTS23R2_ENB_0000_000588_000000_-04-2023-23:30:44+CRT_ASIL_ABIO_pack_2"

        # Result:
            # The logs will be packed into:
            # /home/user/scrambling_processing_dir/__snapshot__/
            # SBTS23R2_ENB_0000_000588_000000_+23-04-2023-23:30:44
            # +CRT_ASIL_ABIO_pack_2__snapshot__.zip

        # Return:
            # output_pkg_path =
            #     "/home/user/scrambling_processing_dir/__snapshot__/"
            #     "SBTS23R2_ENB_0000_000588_000000_+23-04-2023-23:30:44"
            #     "+CRT_ASIL_ABIO_pack_2__snapshot__.zip"
        """
        if self.logs_type == '__nop__' and self.logs:
            original_filename = os.path.basename(self.logs[0])
            match = re.search(r'inspect\.local_(.+)\.tar', original_filename)
            if match:
                version_part = match.group(1)
                nop_versions = version_part.replace('koredump-operator-', 'ko-') \
                    .replace('nokia-sync-operator-', 'nso-') \
                    .replace('ran-nic-sw-controller-', 'rnsc-')
            else:
                nop_versions = "unknown-nop-versions"
            output_pkg_path = os.path.join(self.logs_dirpath, f"{pkg_prefix}_{nop_versions}{self.logs_type}.zip")
        else:
            output_pkg_path = os.path.join(self.logs_dirpath, f"{pkg_prefix}{self.logs_type}.zip")
        if self.logs_type in ('__snapshot__', '__snapshot_vDU__', '__snapshot_vCU__', '__screl_classical__',
                              '__screl_vDU__', '__screl_vCU__', '__nop__'):
            shutil.move(self.logs_new_paths[0], output_pkg_path)
        else:
            with ZipFile(output_pkg_path, mode="w") as zip_obj:
                for log in self.logs_new_paths:
                    zip_obj.write(log, arcname=os.path.basename(log))
        return output_pkg_path
